from chemlib import *
def ball(x,y,r,col): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{col}" stroke="#222"/>'
def lat(x,y,w,big,small,r1,r2):
    d=w*0.35;o=f'<g fill="none" stroke="#777" stroke-dasharray="3 3"><rect x="{x}" y="{y+d}" width="{w}" height="{w}"/><rect x="{x+d}" y="{y}" width="{w}" height="{w}"/><path d="M{x} {y+d} L{x+d} {y} M{x+w} {y+d} L{x+w+d} {y} M{x} {y+d+w} L{x+d} {y+w} M{x+w} {y+d+w} L{x+w+d} {y+w}"/></g>'
    cs=[(x,y+d),(x+w,y+d),(x,y+d+w),(x+w,y+d+w),(x+d,y),(x+w+d,y),(x+d,y+w),(x+w+d,y+w)]
    for a,b in cs:o+=ball(a,b,r1,big)
    for a,b in [(x+w/2,y+d),(x+w/2,y+d+w),(x,y+d+w/2),(x+w,y+d+w/2),(x+w/2+d,y),(x+w/2+d,y+w),(x+d,y+w/2),(x+w+d,y+w/2),(x+w/2+d/2,y+d/2+w/2)]:o+=ball(a,b,r2,small)
    return o
s=page(201,'chem11-solids','Figure 6.12 Structure of NaCl · Figure 6.13 Octahedral Arrangement','شکل 6.12 NaCl کی ساخت · شکل 6.13 ہشت سطحی ترتیب','شکل 6.12 د NaCl جوړښت · شکل 6.13 اتو مخیزه ترتیب','nacl-structure')
add(s,'n1',f'As you can see in figure 6.12, one Na⁺ ion in NaCl is associated with just{SO} one particular Cl⁻ ion. In fact, each Na⁺ ion is equally held by six surrounding Cl{SO} ions and each Cl⁻ ion is surrounded by six Na⁺ ions. Thus co-ordination numb{SO} of each ion is six.',f'جیسا کہ آپ شکل 6.12 میں دیکھ سکتے ہیں، NaCl میں ایک Na⁺ آئن صرف {SO} ایک مخصوص Cl⁻ آئن سے وابستہ ہے۔ دراصل ہر Na⁺ آئن کو چھ اردگرد کے Cl {SO} آئن برابر تھامے ہوئے ہیں اور ہر Cl⁻ آئن چھ Na⁺ آئنوں سے گھرا ہوا ہے۔ اس طرح ہر آئن کا ہم آہنگی عدد {SO} چھ ہے۔',f'لکه څنګه چې تاسو په 6.12 شکل کې ګورئ، په NaCl کې یو Na⁺ آیون یوازې {SO} یو ځانګړي Cl⁻ آیون سره تړلی دی. په حقیقت کې هر Na⁺ آیون د شپږو شاوخوا Cl {SO} آیونونو لخوا په مساوي ډول نیول شوی او هر Cl⁻ آیون د شپږو Na⁺ آیونونو لخوا محاصره دی. په دې توګه د هر آیون همغږي شمېره {SO} شپږ ده.')
add(s,'n2',f'NaCl has a face centered cubic arrangement and in the octahedr{SO} structure, shown in figure 6.13 (a) and (b), Cl⁻ ions may be regarded as having {SO} cubic closed packed (ccp) arrangement in which all octahedral holes are occupi{SO} by Na⁺ ions and same is the case with Cl⁻ ions. The distance between th{SO} adjacent ions of different kinds is 2.815Å (1Å = 10⁻¹⁰m). Thus the two ions are n{SO} touching each other because the sum of their ionic radii is 2.76 Å (0.95+1.81)',f'NaCl کی ترتیب رخ مرکوز مکعبی ہے اور ہشت سطحی {SO} ساخت میں، جو شکل 6.13 (a) اور (b) میں دکھائی گئی ہے، Cl⁻ آئنوں کو {SO} مکعبی بند پیک (ccp) ترتیب والا سمجھا جا سکتا ہے جس میں تمام ہشت سطحی خلا Na⁺ آئنوں سے پُر ہیں {SO} اور یہی معاملہ Cl⁻ آئنوں کا ہے۔ مختلف اقسام کے ملحقہ آئنوں کے درمیان فاصلہ 2.815Å (1Å = 10⁻¹⁰m) ہے۔ یوں دونوں آئن ایک دوسرے کو چھو نہیں رہے {SO} کیونکہ ان کے آئنی نصف قطروں کا مجموعہ 2.76 Å (0.95+1.81) ہے۔',f'NaCl مخ مرکزي مکعبي ترتیب لري او د اتو مخیزه {SO} جوړښت کې، چې په 6.13 (a) او (b) شکل کې ښودل شوی، Cl⁻ آیونونه {SO} مکعبي تړلې ډکې (ccp) ترتیب لرونکي ګڼل کېدای شي چې په هغې کې ټولې اتو مخیزې سوریې د Na⁺ آیونونو لخوا نیول شوې دي {SO} او همدا حال د Cl⁻ آیونونو دی. د بېلابېلو ډولونو د څنګ آیونونو ترمنځ واټن 2.815Å (1Å = 10⁻¹⁰m) دی. په دې توګه دواړه آیونونه یو بل نه لمسوي {SO} ځکه چې د هغوی د آیوني وړانګو مجموعه 2.76 Å (0.95+1.81) ده.')
