def oct_(x,y,w,c1,c2):
    d=w*0.3;o=lat(x,y,w,c1,c2,7,4)
    o+=f'<path d="M{x+w/2+d} {y} L{x+w/2+d} {y+w} M{x+d} {y+w/2} L{x+w+d} {y+w/2} M{x+w/2} {y+d} L{x+w/2} {y+d+w}" stroke="#a02040" stroke-width="1.5" fill="none"/>'
    return o
